    /**
     * Method to retrieve the Loan via LoanFetchOneSummary
     * @param 	summary LoanFetchOneSummary 
     * @return 	LoanFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Loan getLoan( LoanFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "LoanFetchOneSummary arg cannot be null" );
    	
    	Loan entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Loan
        	// --------------------------------------
        	CompletableFuture<Loan> futureEntity = queryGateway.query(new FindLoanQuery( new LoadLoanFilter( summary.getLoanId() ) ), ResponseTypes.instanceOf(Loan.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Loan with id " + summary.getLoanId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


